<script setup>
import { computed,ref } from 'vue'
import bank from '@/data/scene850.json'
import { useLearnerStore } from '@/stores/learner'
import { speakText } from '@/services/audio'
const learner=useLearnerStore(),search=ref(''),module=ref(''),filter=ref(''),page=ref(1),size=40,labels={untested:'未测',unknown:'明确不会',learning:'需巩固',reading:'识读证据',listening:'听读证据',pronunciation:'朗读证据',dictation:'听写证据',active:'使用证据',stable:'稳定运用'}
const modules=Object.entries(bank.meta.source_structure),rows=computed(()=>bank.rows.filter(r=>(!module.value||r.source_category===module.value)&&(!filter.value||learner.model.words[r.lookup]?.state===filter.value)&&(`${r.word} ${r.meaning} ${r.chunk}`).toLowerCase().includes(search.value.toLowerCase()))),visible=computed(()=>rows.value.slice(0,page.value*size))
</script>
<template><section><header class="page-head"><div><span class="section-label">主要学习图谱</span><h1>850词，放回生活里。</h1><p>沿用你提供的10个模块和原表顺序。序号是教学顺序，不是已校准的难度。</p></div><RouterLink to="/learn" class="btn btn-primary">去场景中练</RouterLink></header><div class="module-grid"><button v-for="[name,n] in modules" :key="name" class="module" :class="{selected:module===name}" @click="module=module===name?'':name;page=1"><span>{{name}}</span><b>{{n}}</b></button></div><div class="filters"><input v-model="search" type="search" placeholder="找单词、释义或搭配" aria-label="搜索词库" @input="page=1"/><select v-model="filter" aria-label="掌握状态" @change="page=1"><option value="">所有状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select><span>{{rows.length}}条</span></div><div class="panel vocabulary"><div v-for="r in visible" :key="r.item_id" class="word-row"><div><button class="word reading-font" @click="speakText(r.word)" :aria-label="`听${r.word}`">{{r.word}} <small>▷</small></button><span class="phonetic">{{r.phonetic}}</span><p>{{r.meaning}}</p></div><div class="detail"><span>{{r.source_category}} · 原序{{r.rank}}</span><p>{{r.chunk||'在文章里练习这个词'}}</p></div><span class="state" :class="learner.model.words[r.lookup]?.state">{{labels[learner.model.words[r.lookup]?.state]||'未测'}}</span></div><p v-if="!visible.length" class="muted">没有匹配的词。</p></div><button v-if="visible.length<rows.length" class="btn btn-secondary more" @click="page++">再看40词</button><p class="source-note">原表待补例句不会展示成正式教学内容。校订释义保留原始字段，词库变化可追溯。</p></section></template>
<style scoped>.module-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:25px 0}.module{display:flex;justify-content:space-between;gap:8px;border:1px solid var(--line);background:#fff;border-radius:12px;padding:15px;font-size:12px}.module b{color:var(--ink-muted);font-weight:500}.module.selected{background:var(--brand-soft);border-color:var(--brand)}.filters{display:flex;align-items:center;gap:12px;margin:23px 0}.filters input{flex:1}.filters span{font-size:12px;color:var(--ink-muted);white-space:nowrap}.vocabulary{padding:0 24px}.word-row{display:grid;grid-template-columns:1fr 1.2fr 90px;align-items:center;gap:20px;border-bottom:1px solid var(--line);padding:19px 0}.word-row:last-child{border:0}.word{border:0;background:transparent;padding:0;font-size:24px;color:var(--ink);text-align:left}.word small{font-size:13px;color:var(--brand)}.phonetic{font-size:11px;margin-left:12px;color:var(--ink-muted)}.word-row p{margin:5px 0 0;font-size:13px}.detail span{font-size:11px;color:var(--ink-muted)}.detail p{color:var(--brand)}.state{font-size:11px;background:#f2f5f3;padding:5px 10px;text-align:center;border-radius:20px}.state.unknown,.state.learning{background:#fff3e4;color:#8c642d}.more{margin:22px auto;display:flex}.source-note{font-size:11px;color:var(--ink-muted)}@media(max-width:750px){.module-grid{grid-template-columns:1fr 1fr}.word-row{grid-template-columns:1fr 80px}.detail{display:none}.filters{flex-wrap:wrap}.filters input{min-width:180px}}</style>
